(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["nl"] = {"ui":{"skip":"Ga naar de inhoud","back":"← Terug naar AI-gile","lang.button":"Taal: {name}","lang.dialog":"Kies een taal","lang.search":"Zoek een taal","lang.none":"Geen taal gevonden","lang.notYet":"{name} is nog niet vertaald","theme.aria":"Wissel tussen licht en donker thema","theme.toLight":"Naar het lichte thema","theme.toDark":"Naar het donkere thema","index.title":"AI-gile: je AI-devteam, op één bord","index.description":"AI-gile is een kanbanbord voor AI-codeerteams. Zij werken terwijl jij slaapt; jij krijgt één korte stapel met dingen om te beslissen, te testen en goed te keuren.","hero.logoAlt":"AI-gile-bordicoon","hero.h1.html":"Je AI-devteam, op één&nbsp;bord.","hero.alpha":"🐣 Gesloten pre-alpha","hero.alphaTitle":"Vroeg en onaf: fijn dat je het probeert!","hero.lede":"Ze bouwen terwijl jij slaapt. Jij wordt wakker bij één korte stapel: een paar vragen, een paar dingen om te testen, een paarse diamant of twee. Klikken, goedkeuren, terug naar je koffie.","dl.windows":"Windows-app","dl.browser":"Gebruik het in je browser","dl.soon":"Binnenkort","dl.notify":"🔔 Laat het me weten als het opengaat","dl.notifySmall":"Alpha of bèta","hero.secondary":"Agile, maar het team heeft nooit een stand-upkoffie nodig. (Ze houden de stand-ups wel.)","pitch.h2":"AI-gile in zoveel woorden als je wilt","pitch.lede":"Kies een lengte, van één woord tot 144. Elke lengte is een eigen beschrijving, voor die maat geschreven. Sleep de schuif of gebruik de pijltjestoetsen.","pitch.rangeLabel":"Lengte in woorden","pitch.dice":"🎲 nog een versie","pitch.words.one":"{n} woord","pitch.words.other":"{n} woorden","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} teken","pitch.chars.other":"{n} tekens","count.line.html.one":"{n} kaart op het bord op dit moment","count.line.html.other":"{n} kaarten op het bord op dit moment","features.aria":"Wat het doet","f.pile.h":"Eén stapel voor jou","f.pile.html":"<b>Voor jou</b> bevat alles wat op jou wacht, over alle projecten heen: vragen, dingen om te testen, taken die alleen een mens kan doen. Je wachtrij laat zien wat er nu aan de beurt is en hoe lang het duurt.","f.sleep.h":"Teams die werken terwijl jij slaapt","f.sleep.p":"Elk project heeft een lead en een team van AI-agents. Reageer op een kaart en het team wordt wakker, doet het werk en geeft het terug met stappen die een moe mens kan volgen.","f.tester.h":"Eerst checkt een AI-tester","f.tester.p":"Voordat iets bij jou komt, volgt een tester de stappen in een kopie van de app en laat zien wat hij zag, met een screenshot. Blader door wat geslaagd is en keur het goed met één klik.","f.proof.h":"Bewijs, geen beloftes","f.proof.p":"Elke overdracht laat zien wat er veranderd is: de bestanden, de diff, de screenshots. Je hoeft niet elke app open te doen om te zien of iets af is.","f.chat.h":"Chat met je leads","f.chat.p":"Een balk in Discord-stijl: één icoon per project, paarse diamanten voor wat jou nodig heeft. Stuur een lead een idee; die maakt er kaarten en een plan van, met een ✅ Go-knop.","f.tidy.h":"Houdt zichzelf netjes","f.tidy.p":"Verwante kaarten gaan samen, warrige titels worden rechtgezet en een tokencheck houdt de code slank. Minder om tussen te wisselen, minder om over na te denken.","f.private.h":"Van jou, op je eigen computer","f.private.li1":"Het bord draait op je eigen machine en luistert alleen naar jou.","f.private.li2":"Privéberichten tussen mensen zijn end-to-end versleuteld.","f.private.li3":"Geen accounts, geen trackers, geen cookies.","f.lang.h":"In jouw taal","f.lang.p":"Meer dan 120 talen, van Nederlands, Welsh en Japans tot piraat, Yoda en Klingon, met een snelle terugschakelaar naar Engels voor de ontwikkelaarswoorden.","tl.aria":"Tijdlijn van het eerste gesprek tot de roadmap","tl.h2":"Van het eerste gesprek tot wat er komt","tl.lede":"Echte data en tijden, in je eigen tijdzone. Na vandaag is het het plan, zonder beloofde data.","tl.today":"Vandaag","tl.planned":"gepland","tl.cards.one":"{n} kaart","tl.cards.other":"{n} kaarten","join.h2":"Doe mee","join.lede":"AI-gile wordt gebouwd door één klein mens en een flink aantal geduldige agents. Voorlopig is het privé, een gesloten alpha met vrienden. Zin om mee te doen als het opengaat?","join.btn":"Meld je interesse","join.small":"We mailen je, verder niets","footer.tag":"AI-gile. Geen trackers, geen cookies, geen stand-upkoffie.","footer.licence":"Zakelijke licentie","footer.status":"Status","form.sending":"Versturen…","form.failed":"Dat lukte niet: probeer het later opnieuw.","form.offline":"AI-gile was niet bereikbaar: probeer het later opnieuw.","interest.title":"AI-gile: laat me weten wanneer de alpha opengaat","interest.description":"Laat je e-mailadres achter om te horen wanneer de gesloten alpha of bèta van AI-gile opengaat.","interest.h1":"🔔 Laat het me weten als het opengaat","interest.lede":"AI-gile zit in een gesloten pre-alpha. Laat je e-mailadres achter en we schrijven één keer, zodra er een plek voor je is.","interest.email":"Je e-mailadres","interest.which":"Welke test?","interest.alpha":"Gesloten alpha: vroeg, ruw, veel veranderingen","interest.beta":"Bèta: rustiger, later","interest.both":"Allebei goed, wat het eerst komt","interest.submit":"Zet me op de lijst","interest.thanks":"Bedankt! Je staat op de lijst.","interest.kept":"Alleen je e-mailadres en de gekozen test worden bewaard, alleen voor deze lijst. Geen nieuwsbrief, geen trackers.","licence.title":"AI-gile: zakelijke licentie","licence.description":"Gebruik je AI-gile voor je bedrijf? Vraag een gratis zakelijke licentie aan.","licence.h1":"📜 Zakelijke licentie","licence.lede":"Gebruik je AI-gile op je werk? Vertel ons wie je bent en wat je doet. Als het iets goeds oplevert, is de licentie gratis.","licence.company":"Bedrijf","licence.website":"Website","licence.what":"Wat je doet","licence.how":"Hoe het de wereld helpt","licence.email":"E-mailadres","licence.submit":"Aanvragen","licence.thanks":"Bedankt! We antwoorden per e-mail.","status.title":"AI-gile-status","status.h1":"AI-gile-status","status.quiet":"Alles rustig","status.checking":"Controleren…","status.offline":"De statusdienst is nu niet bereikbaar (we proberen opnieuw)","status.updated":"bijgewerkt {ago}","status.justNow":"zojuist","status.min":"{n} min geleden","status.hours":"{n} u geleden","status.days":"{n} d geleden"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Gedelegeerd."]},{"n":2,"texts":["Robots werken.","Agents, geordend.","Ideeën, gebouwd."]},{"n":3,"texts":["Kanban voor robots.","Ideeën worden functies.","Gratis, lokaal, getest."]},{"n":5,"texts":["Kanbanbord waar agents het bouwen.","Jij schrijft kaarten. Agents bouwen.","Gratis, lokaal, getest, beetje gek."]},{"n":8,"texts":["Een gratis kanbanbord waar AI-agents aan het werk gaan.","Schrijf een idee. Agents bouwen het. Jij keurt goed.","Agile voor één mens en veel geduldige robots."]},{"n":13,"texts":["Een kanbanbord op je eigen computer waar AI-agents de kaarten oppakken.","Schrijf een idee. Een team agents bouwt het. Een tester checkt het.","Gratis, zonder accounts of trackers: een bord, wat robots, en jij als baas."]},{"n":21,"texts":["AI-gile is een kanbanbord om met AI-codeeragents te werken. Zij pakken de kaarten op; jij test ze en keurt ze goed.","Elk project krijgt een lead en een team van AI-agents. Reageer op een kaart en het team gaat aan de slag.","Een gratis, persoonlijk takenbord dat op je eigen computer draait. De werkers zijn robots. Degene die ja zegt, ben jij."]},{"n":34,"texts":["Je zet ideeën op een bord. Een team van AI-agents maakt er werkende functies van, test ze en geeft ze terug met stappen om uit te proberen. Niets telt als af totdat jij het zegt.","AI-gile is een zelfgemaakt kanbanbord dat Rich bouwde met veel hulp van de agents die het nu beheert. Het is gratis, draait op je computer en wordt gedeeld met vrienden, niet verkocht.","Stel je een gewoon kanbanbord voor, met kolommen van Backlog tot Klaar, behalve dat de kaarten door AI-agents worden opgepakt. Ze melden de voortgang, vragen om hulp als ze vastzitten en wachten altijd op jouw duimpje omhoog."]},{"n":55,"texts":["AI-gile is een kanbanbord waar het team uit AI-agents bestaat. Elk project heeft een lead die het werk plant en helpers die het bouwen. Is een functie klaar, dan probeert een AI-tester hem uit en maakt een screenshot, waarna hij op jouw stapel belandt. Keur hem goed, of reageer en ze werken hem om.","Het begon als de manier van één persoon om al die AI-codeersessies tegelijk bij te houden, en groeide uit tot een echt bord. Het draait op je machine, vraagt geen account en heeft geen trackers. Het is gratis voor vrienden en nieuwsgierigen. Het is ook onaf, dus verwacht ruwe kantjes en af en toe een verrassing.","Dit is de eerlijke versie. De ideeën moet je nog steeds zelf hebben en de resultaten moet je nog steeds zelf checken. Wat AI-gile doet, is alles daartussen: het houdt de kaarten op orde, wekt de juiste agent als jij reageert, laat precies zien wat er veranderd is en houdt alles in één korte stapel voor jou."]},{"n":89,"texts":["AI-gile is een gratis kanbanbord dat je op je eigen computer draait. In plaats van mensen heeft elk project een team van AI-agents: een lead die jouw ideeën omzet in kaarten en een plan, en helpers die de kaarten op volgorde van prioriteit oppakken. Is iets gebouwd, dan volgt een AI-tester de teststappen en laat hij zien wat hij zag. Daarna wacht het op één stapel met de naam Voor jou. Jij keurt het goed, of je reageert en het team probeert het opnieuw. Niets bereikt ooit Klaar zonder jou.","Een paar functies die je misschien niet verwacht. Een nachtwacht houdt de kolom Te doen gevuld terwijl jij slaapt en kiest kaarten waarvoor geen antwoord van jou nodig is. Een tokenteller toont hoeveel de agents vandaag en deze week gebruikten, en de Geen-tokenmodus zegt ze te stoppen met uitgeven. Je kunt vrienden berichten sturen, en privéberichten zijn end-to-end versleuteld. Het bord spreekt zo'n 120 talen, waaronder Nederlands, Vlaams, piraat en Klingon. Niets daarvan kost een cent, en niemand probeert het je ook te verkopen.","AI-gile is een klein, persoonlijk project, geen bedrijf. Rich wilde meerdere AI-codeerprojecten in de gaten houden zonder elke app open te doen, dus bouwden hij en de agents er een bord voor, en gebruikten dat bord om de rest van zichzelf te bouwen. Het zit in een gesloten pre-alpha, wat betekent dat het werkt, meestal, voor een handvol vrienden. Er is geen prijzenpagina, geen nieuwsbrief en geen groeiplan. Klinkt het handig, dan kun je vragen om het te proberen zodra het wat verder opengaat."]},{"n":144,"texts":["AI-gile is een kanbanbord voor één mens en een heleboel AI-agents. Het draait op je eigen computer en is helemaal gratis. Je voegt projecten toe, en elk project krijgt een lead en een klein team. Je chat met de lead, een beetje zoals op Discord, en beschrijft een idee; de lead maakt er kaarten en een plan van en wacht tot jij op Go drukt. Het team werkt de kaarten af op volgorde van prioriteit, met een eenvoudige opdrachtregel die voor taalmodellen is gemaakt. Voordat er iets naar jou terugkomt, volgt een AI-tester de stappen in een kopie van de app en voegt een screenshot toe. Klaar werk belandt op je stapel, met de gewijzigde bestanden en de diff. Jij keurt het goed, of je laat een reactie achter en het team wordt wakker en probeert het opnieuw. Alleen jij kunt een kaart naar Klaar verplaatsen.","Een dag met AI-gile, ongeveer. 's Avonds laat je een paar reacties achter: deze knop staat op de verkeerde plek, die lijst moet gesorteerd worden, kunnen we een donkere modus krijgen. Je gaat naar bed. De agents lezen de reacties, voeren de wijzigingen door, testen ze en geven ze terug. Raakt Te doen leeg, dan vult de nachtwacht de kolom uit de backlog aan met kaarten waar geen antwoord van jou voor nodig is. 's Ochtends ligt er één korte stapel: een paar vragen en een paar dingen om uit te proberen, elk met stappen die een slaperig mens kan volgen en een screenshot van hoe het werkt. Je klikt erdoorheen, keurt de goede goed en stuurt de rest terug. Een tokenteller laat zien wat het allemaal gebruikte, en de Geen-tokenmodus is er voor magere weken. Daarna ontbijt je, daar kunnen de agents nog niet bij helpen.","Eerst wat AI-gile niet is. Het is geen startup, het is niet te koop en niemand verzamelt je gegevens. Het is een gratis bord dat op je computer draait, zonder accounts, zonder trackers en zonder cookies. Wat het wel is: één nette plek om al je AI-codeerprojecten tegelijk te zien, met een team agents dat de kaarten doet en jij die de beslissingen neemt. Het voegt verwante kaarten samen, herstelt warrige titels en houdt in de gaten hoe slank de code blijft. Het spreekt zo'n 120 talen, van Nederlands en Vlaams tot piraat en Klingon. Vrienden kunnen elkaar berichten sturen, privé en versleuteld. Het is gebouwd door Rich en een groot aantal geduldige agents, die vooral zichzelf gebruikten. Het zit in een gesloten pre-alpha, dus op sommige plekken is het ruw. Klinkt het leuk, vraag het dan netjes en misschien kom je er vroeg in."]}],"quips":{"1":"Eén woord. Gedurfd. Misschien te gedurfd.","3":"Drie woorden. Al eerlijker dan de meeste productpagina's.","8":"Acht woorden. Nog steeds korter dan een stand-up.","21":"De lengtes zijn trouwens story points. Natuurlijk zijn ze dat.","55":"Vijfenvijftig woorden. Terwijl je dit las, zijn er twee kaarten afgekomen.","144":"Dat was de lange. Een 233 bestaat niet. De agents zijn naar bed."}},"timeline":{"first-idea.name":"Het eerste idee","first-idea.line":"Het allereerste gesprek, voordat er ook maar één regel code was.","first-board.name":"Het eerste bord","first-board.line":"Een bord dat zijn eigen bouw bijhoudt: kaarten, kolommen, slepen en neerzetten, projecten.","team-roles.name":"Team en rollen","team-roles.line":"Agentprofielen, teamsjablonen, ruimtes en wie wat doet.","install.name":"Installeren en releases","install.line":"Een zipbestand dat een vriend kan installeren, updates, kanalen en terugdraaien.","usage-saver.name":"Verbruiksbesparing","usage-saver.line":"Meten wat runs kosten, de code slank houden, je limiet sparen.","friends.name":"Vrienden en delen","friends.line":"Privéberichten, een versleutelde relay, uitnodigingen, rollen en gedeelde projecten.","languages.name":"Talen","languages.line":"Elke schermtekst in een taalbestand, met Nederlands en Vlaams als eerste.","ai-tester.name":"AI-tester","ai-tester.line":"Een tester checkt elke overdracht eerst en laat zien wat hij zag.","website.name":"De website","website.line":"aigile.lol, de teaser en deze tijdlijn.","streaming.name":"Chat en streamen","streaming.line":"Discord, Twitch, OBS, streamermodus, GIF's en emoji's.","no-ai.name":"Editie zonder AI","no-ai.line":"Een bord voor mensen die zonder AI programmeren, en openbare borden.","night-watch.name":"Nachtwacht","night-watch.line":"Een wachter en een Scrum Master houden de teams bij de les terwijl jij slaapt.","p-more.name":"Al het andere","p-more.line":"Kleinere ideeën die nog op hun beurt wachten.","p-android.name":"Telefoon en Android","p-android.line":"Je bord bereiken vanaf je telefoon, daarna een eigen Android-app.","p-release.name":"Alpha en verder","p-release.line":"Gesloten alpha, de live site, daarna de bèta.","p-languages.name":"Meer talen","p-languages.line":"Meer dan honderd talen, en een onderdompelmodus voor wie een taal leert.","p-engines.name":"Meer AI-engines","p-engines.line":"Kies per agent Claude, Codex of Gemini.","p-pro.name":"Professionele werkwijze","p-pro.line":"Risicolabels, merge-poorten, incidentkaarten en vangrails.","p-self.name":"Zorg voor jezelf","p-self.line":"Moemodus, herinneringen om goed voor jezelf te zorgen en 4:20.","p-servers.name":"Servers en schaal","p-servers.line":"Globale serverinstellingen, rollen en plannen voor groei.","p-livestream.name":"Extra's voor streamen","p-livestream.line":"Twitch-chat, eigen emoji's en een openbaar live-overzicht."}};
